package io.fireflysoftware.core.insurance.underwriting.core.services.governance.impl;

import io.fireflysoftware.core.insurance.underwriting.core.services.quotes.QuoteTenantBindingResolver;
import io.fireflysoftware.core.insurance.underwriting.interfaces.governance.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.fireflyframework.security.api.domain.SecurityPrincipal;
import org.fireflyframework.security.adapter.opa.OpaPolicyEvaluationAdapter;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import org.springframework.web.reactive.function.client.*;
import reactor.core.publisher.Mono;
import static org.junit.jupiter.api.Assertions.*;

/** Controlled real OPA adapter and CURRENT SPI; this does not establish native signed HTTP acceptance. */
class CurrentStaffUnderwritingAdmissionTest {
    final Instant now=Instant.parse("2026-11-01T12:00:00Z");final String issuer="https://synthetic-staff.invalid",tenant="opaque:insurer:tenant",digest="a".repeat(64);
    final UUID sourceParty=UUID.randomUUID(),sourceProduct=UUID.randomUUID(),resource=UUID.randomUUID(),binding=UUID.randomUUID(),status=UUID.randomUUID(),staffActor=UUID.randomUUID();
    final AtomicInteger evaluations=new AtomicInteger(),lookups=new AtomicInteger(),work=new AtomicInteger();
    final AtomicReference<SecurityPrincipal> current=new AtomicReference<>(principal("STAFF",tenant,"registered-staff",List.of("underwriting-audience"),Set.of("insurance:underwriting:referrals:create")));
    String response="{\"result\":{\"allow\":true,\"policy_revision\":\"delegation-policy-3\"},\"decision_id\":\"owner-pdp-%d\"}";boolean changeBinding,changePrincipal;
    SecurityPrincipal principal(String kind,String namespace,String client,List<String> audience,Set<String> scopes){return SecurityPrincipal.builder().issuer(issuer).subject("opaque-staff-subject").tenantId(namespace).scopes(scopes).claims(Map.of("principal_kind",kind,"staff_actor_id",staffActor.toString(),"tenant_id",namespace,"client_id",client,"aud",audience,"exp",now.plusSeconds(60),"nbf",now.minusSeconds(1))).build();}
    GovernedUnderwritingIntent intent(){return new GovernedUnderwritingIntent(GovernedUnderwritingIntent.Operation.REFERRAL_CREATE,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),null,0,null,"Property review");}
    CurrentStaffUnderwritingAdmissionImpl authority(){
        QuoteTenantBindingResolver resolver=(principal,expected,original,until,remaining)->{int call=lookups.incrementAndGet();return Mono.just(new QuoteTenantBindingResolver.Observation(issuer,tenant,resource,binding,changeBinding && call>1?2:1,digest,1,0,status,0,now,now.plusSeconds(5),now.plusSeconds(60)));};
        var pdp=new OpaPolicyEvaluationAdapter(WebClient.builder().baseUrl("https://synthetic-pdp.invalid").exchangeFunction(request->{int call=evaluations.incrementAndGet();if(changePrincipal)current.set(principal("HUMAN",tenant,"registered-staff",List.of("underwriting-audience"),Set.of("insurance:underwriting:referrals:create")));return Mono.just(ClientResponse.create(HttpStatus.OK).header(HttpHeaders.CONTENT_TYPE,"application/json").body(response.formatted(call)).build());}).build(),"insurance/underwriting/decision");
        return new CurrentStaffUnderwritingAdmissionImpl(()->Mono.just(current.get()),pdp,resolver,new CurrentStaffUnderwritingAdmissionImpl.Profile(issuer,"underwriting-audience","registered-staff",tenant,resource,"canonical-insurer-staff","TERM_PC_PROPERTY"),Clock.fixed(now,ZoneOffset.UTC),System::nanoTime,UUID::randomUUID);
    }
    @Test void actualSameResponsePdpIdentifiersAndCurrentOpaqueMappingAreRetained(){var r=intent();var a=authority();var result=a.execute(r,r.intentDigest(resource),p->a.observeLockedSource(p,new io.fireflysoftware.core.insurance.underwriting.models.governance.UnderwritingGovernanceRows.Source(resource,r.submissionId(),sourceParty,sourceProduct,r.riskId(),sourceParty,"PROPERTY","QUOTED","PROPERTY","USD",UUID.randomUUID(),1,new java.math.BigDecimal("100000.00"),"USD",OffsetDateTime.ofInstant(now,ZoneOffset.UTC),OffsetDateTime.ofInstant(now,ZoneOffset.UTC))).then(a.revalidate(p)).then(a.requireDecisionEvidence(p)).map(e->{work.incrementAndGet();assertEquals("owner-pdp-1",e.authorization().decisionId());assertEquals("owner-pdp-2",e.admission().decisionId());assertEquals(tenant,p.actor().platformTenantId());assertEquals(resource,p.resourceTenantId());return new GovernedUnderwritingCommandResponse(GovernedUnderwritingCommandResponse.Status.REFUSED,r.actionId(),p.request().intentDigest(),null);})).block(Duration.ofSeconds(2));assertNotNull(result);assertEquals(1,work.get());assertEquals(2,evaluations.get());}
    @Test void aHumanCannotBorrowTheStaffOwnerPurpose(){current.set(principal("HUMAN",tenant,"registered-staff",List.of("underwriting-audience"),Set.of("insurance:underwriting:referrals:create")));var r=intent();assertThrows(SecurityException.class,()->authority().execute(r,r.intentDigest(resource),p->{work.incrementAndGet();return Mono.empty();}).block());assertEquals(0,lookups.get());assertEquals(0,evaluations.get());assertEquals(0,work.get());}
    @Test void wrongRegisteredClientAudienceOrOpaqueNamespaceRefusesBeforeCurrentLookup(){for(var principal:List.of(principal("STAFF",tenant,"foreign-client",List.of("underwriting-audience"),Set.of("insurance:underwriting:referrals:create")),principal("STAFF",tenant,"registered-staff",List.of("underwriting-audience","extra-audience"),Set.of("insurance:underwriting:referrals:create")),principal("STAFF",resource.toString(),"registered-staff",List.of("underwriting-audience"),Set.of("insurance:underwriting:referrals:create")))){current.set(principal);var r=intent();assertThrows(SecurityException.class,()->authority().execute(r,r.intentDigest(resource),p->Mono.empty()).block());}assertEquals(0,lookups.get());assertEquals(0,evaluations.get());}
    @Test void broaderIncomingScopesCannotBorrowAnExactOwnerOperation(){current.set(principal("STAFF",tenant,"registered-staff",List.of("underwriting-audience"),Set.of("insurance:underwriting:referrals:create","insurance:underwriting:referrals:approve")));var r=intent();assertThrows(SecurityException.class,()->authority().execute(r,r.intentDigest(resource),p->Mono.empty()).block());assertEquals(0,evaluations.get());}
    @Test void changedCurrentBindingCannotProduceAdmissionEvidence(){changeBinding=true;var r=intent();var a=authority();assertThrows(SecurityException.class,()->a.execute(r,r.intentDigest(resource),p->a.observeLockedSource(p,new io.fireflysoftware.core.insurance.underwriting.models.governance.UnderwritingGovernanceRows.Source(resource,r.submissionId(),sourceParty,sourceProduct,r.riskId(),sourceParty,"PROPERTY","QUOTED","PROPERTY","USD",UUID.randomUUID(),1,new java.math.BigDecimal("100000.00"),"USD",OffsetDateTime.ofInstant(now,ZoneOffset.UTC),OffsetDateTime.ofInstant(now,ZoneOffset.UTC))).then(a.revalidate(p)).then(a.requireDecisionEvidence(p)).then(Mono.empty())).block());assertEquals(0,work.get());}
    @Test void aPermitWithoutItsPrivateExecutionCannotBeReused(){var r=intent();var a=authority();final AtomicReference<io.fireflysoftware.core.insurance.underwriting.core.services.governance.StaffUnderwritingAdmission.Permit> retained=new AtomicReference<>();a.execute(r,r.intentDigest(resource),p->{retained.set(p);return Mono.just(new GovernedUnderwritingCommandResponse(GovernedUnderwritingCommandResponse.Status.REFUSED,r.actionId(),p.request().intentDigest(),null));}).block();assertThrows(SecurityException.class,()->a.revalidate(retained.get()).block());}
    @Test void unprovenancedPermitAndChangedNativePrincipalCannotReachBusiness(){var r=intent();response="{\"result\":{\"allow\":true,\"policy_revision\":\"delegation-policy-3\"}}";assertThrows(SecurityException.class,()->authority().execute(r,r.intentDigest(resource),p->{work.incrementAndGet();return Mono.empty();}).block());assertEquals(0,work.get());}
    @Test void aChangedNativePrincipalAfterPdpCannotReceiveAdmission(){changePrincipal=true;var r=intent();assertThrows(SecurityException.class,()->authority().execute(r,r.intentDigest(resource),p->{work.incrementAndGet();return Mono.empty();}).block());assertEquals(0,work.get());}
    @Test void terminalExpectedDigestCannotBeReplacedBeforeAnyBusinessWork(){var r=intent();assertThrows(SecurityException.class,()->authority().execute(r,"b".repeat(64),p->{work.incrementAndGet();return Mono.empty();}).block());assertEquals(0,work.get());assertEquals(0,evaluations.get());}
    @Test void nestedOwnerCommandCannotStartAnotherAuthorizationOrBusinessCallback(){var first=intent();var second=intent();var a=authority();var denied=new AtomicBoolean();var result=a.execute(first,first.intentDigest(resource),permit->a.revalidate(permit).then(Mono.defer(()->{int beforePdp=evaluations.get(),beforeLookup=lookups.get();return a.execute(second,second.intentDigest(resource),nested->{work.incrementAndGet();return Mono.empty();}).onErrorResume(SecurityException.class,error->{denied.set(true);assertEquals(beforePdp,evaluations.get());assertEquals(beforeLookup,lookups.get());return Mono.just(new GovernedUnderwritingCommandResponse(GovernedUnderwritingCommandResponse.Status.REFUSED,first.actionId(),first.intentDigest(resource),null));});}))).block();assertNotNull(result);assertTrue(denied.get());assertEquals(0,work.get());assertEquals(1,evaluations.get());}
    @Test void savedPermitCannotBeBorrowedByANewCurrentExecutionOrAfterCompletion(){var first=intent();var second=intent();var a=authority();var retained=new AtomicReference<io.fireflysoftware.core.insurance.underwriting.core.services.governance.StaffUnderwritingAdmission.Permit>();var result=a.execute(first,first.intentDigest(resource),permit->{retained.set(permit);return a.revalidate(permit).thenReturn(new GovernedUnderwritingCommandResponse(GovernedUnderwritingCommandResponse.Status.REFUSED,first.actionId(),first.intentDigest(resource),null));}).block();assertNotNull(result);assertThrows(SecurityException.class,()->a.revalidate(retained.get()).block());assertThrows(SecurityException.class,()->a.requireDecisionEvidence(retained.get()).block());assertThrows(SecurityException.class,()->a.execute(second,second.intentDigest(resource),currentPermit->a.revalidate(retained.get()).then(Mono.defer(()->{work.incrementAndGet();return Mono.just(new GovernedUnderwritingCommandResponse(GovernedUnderwritingCommandResponse.Status.REFUSED,second.actionId(),second.intentDigest(resource),null));}))).block());assertEquals(0,work.get());}
}
